{
  name: 'Новая модалка фильтров',
  args: {
    title: 'Поиск курсов',
    buttonTitle: 'Показать 128 курсов',
    hasCloseButton: true,
    isLoading: false,
    disabled: false
  },
  render: args => ({
    components: {
      BaseButton,
      BaseFilter,
      BaseFilterModalNew,
      BaseFilterWithImage
    },
    setup() {
      const isOpen = ref(false);
      const categories = ['Python', 'Аналитика', 'Дизайн', 'Маркетинг', 'Frontend', 'Backend', 'DevOps', 'Product'];
      const cards = [{
        title: 'Популярное',
        image: {
          src: '/courses-web/images/filters/star.png',
          alt: 'Звезда'
        }
      }, {
        title: 'Скидки',
        image: {
          src: '/courses-web/images/filters/money.png',
          alt: 'Деньги'
        }
      }, {
        title: 'С отзывами',
        image: {
          src: '/courses-web/images/filters/comment.png',
          alt: 'Комментарии'
        }
      }];
      return {
        args,
        cards,
        categories,
        isOpen
      };
    },
    template: `
      <div class="min-h-[920px] bg-ui-black-50 p-8">
        <BaseButton size="m" @click="isOpen = true">Открыть новую модалку</BaseButton>

        <BaseFilterModalNew
          v-if="isOpen"
          v-bind="args"
          @close="isOpen = false"
          @apply-filter="isOpen = false"
          @reset-filter="args.buttonTitle = 'Показать все курсы'"
        >
          <div class="my-1 grid gap-8 py-1">
            <section class="grid gap-4">
              <div class="text-body font-semibold">Рекомендуем</div>
              <div class="flex gap-3 overflow-x-auto pb-1">
                <BaseFilterWithImage
                  v-for="card in cards"
                  :key="card.title"
                  :title="card.title"
                  :image="card.image"
                  :active="card.title === 'Популярное'"
                />
              </div>
            </section>

            <section class="grid gap-4">
              <div class="text-body font-semibold">Направление</div>
              <div class="flex flex-wrap gap-2">
                <BaseFilter
                  v-for="category in categories"
                  :key="category"
                  appearance="edu"
                  :active="category === 'Python'"
                >
                  {{ category }}
                </BaseFilter>
              </div>
            </section>

            <section class="grid gap-3">
              <div class="text-body font-semibold">Дополнительный контент</div>
              <div
                v-for="index in 8"
                :key="index"
                class="rounded-2xl border border-solid border-ui-black-100 p-4 text-small text-ui-black-500"
              >
                Блок {{ index }} нужен, чтобы проверить скролл и появление разделителей в шапке и футере.
              </div>
            </section>
          </div>
        </BaseFilterModalNew>

        <div id="modal-target"></div>
      </div>
    `
  }),
  argTypes: {
    title: {
      control: 'text'
    },
    buttonTitle: {
      control: 'text'
    },
    hasCloseButton: {
      control: 'boolean'
    },
    isLoading: {
      control: 'boolean'
    },
    disabled: {
      control: 'boolean'
    }
  }
}

{
  name: 'Базовая модалка фильтров',
  args: {
    title: 'Фильтры',
    activeCount: 3,
    hasCloseButton: true,
    disabled: false
  },
  render: args => ({
    components: {
      BaseButton,
      BaseFilter,
      BaseFilterModal
    },
    setup() {
      const isOpen = ref(false);
      const filters = ['Все', 'Онлайн', 'С сертификатом', 'Со скидкой'];
      return {
        args,
        isOpen,
        filters
      };
    },
    template: `
      <div class="min-h-[720px] bg-ui-black-50 p-8">
        <BaseButton size="m" @click="isOpen = true">Открыть фильтры</BaseButton>

        <BaseFilterModal
          v-if="isOpen"
          v-bind="args"
          @close="isOpen = false"
          @apply-filter="isOpen = false"
          @reset-filter="args.activeCount = 0"
        >
          <div class="grid gap-6 p-3">
            <div class="text-body font-semibold">Формат обучения</div>
            <div class="flex flex-wrap gap-2">
              <BaseFilter
                v-for="filter in filters"
                :key="filter"
                :active="filter === 'Онлайн'"
              >
                {{ filter }}
              </BaseFilter>
            </div>
            <div class="text-body font-semibold">Описание</div>
            <div class="text-small text-ui-black-500">
              Пример контента внутри базовой модалки фильтров для Storybook.
            </div>
          </div>
        </BaseFilterModal>

        <div id="modal-target"></div>
      </div>
    `
  }),
  argTypes: {
    title: {
      control: 'text'
    },
    activeCount: {
      control: 'number'
    },
    hasCloseButton: {
      control: 'boolean'
    },
    disabled: {
      control: 'boolean'
    }
  }
}

