{
  args: {
    sectionKey: 'services',
    width: 220
  },
  render: args => ({
    components: {
      HeaderDropdown,
      HeaderLogo
    },
    setup() {
      return {
        args,
        sectionsMap
      };
    },
    template: `
      <div class="p-20 h-[500px] bg-main-gradient-first">
        <HeaderDropdown
          :section="sectionsMap[args.sectionKey]"
          :width="args.width"
        >
          <template #name>
            <HeaderLogo v-if="args.sectionKey === 'services'" />
            <span v-if="args.sectionKey === 'services'" class="ml-2 h-6 border-l border-l-ui-white-transparent-50"></span>

            <span v-if="args.sectionKey === 'courses'" class="mr-0.5 text-small text-ui-white">
              {{ sectionsMap.courses.title }}
            </span>
          </template>

          <template #title v-if="args.sectionKey === 'services'">
            <div class="text-small font-bold text-ui-black-850">
              {{ sectionsMap.services.title }}
            </div>
          </template>
        </HeaderDropdown>
      </div>
    `
  }),
  argTypes: {
    sectionKey: {
      options: ['services', 'courses'],
      control: {
        type: 'radio'
      },
      name: 'section'
    },
    width: {
      control: {
        type: 'number',
        min: 160,
        max: 400,
        step: 10
      }
    }
  }
}

